css:
.dcx,.dcx{margin:0;padding:0;background:#FFFFFF;font-family:'Plus Jakarta Sans',system-ui,sans-serif;color:#0B2018;-webkit-font-smoothing:antialiased}
.dcx a{color:#0B3B29;text-decoration:none}
.dcx a:hover{color:#0E8A52}
.dcx [data-row]>a,.dcx [data-nav] a,.dcx header a{white-space:nowrap;flex-shrink:0}
@media (min-width:1300px){.dcx [data-z]{zoom:1.25}
}
@media (max-width:1040px){.dcx [data-nav]{display:none!important}
.dcx [data-hero]{flex-direction:column;height:auto!important}
.dcx [data-heroimg]{position:relative!important;width:100%!important;height:auto!important;right:auto!important;-webkit-mask-image:none!important;mask-image:none!important}
.dcx [data-c]{grid-template-columns:minmax(0,1fr)!important;justify-items:center;row-gap:24px}
.dcx [data-c]>*{max-width:100%}
.dcx [data-g4]{grid-template-columns:repeat(2,minmax(0,1fr))!important;row-gap:24px}
.dcx [data-g4]>*{border:0!important;padding-left:0!important}
}
@media (max-width:600px){.dcx [data-h1]{font-size:38px!important;line-height:44px!important}
.dcx [data-row]{flex-wrap:wrap}
.dcx [data-g4]{grid-template-columns:minmax(0,1fr)!important}
}
@media (max-width:1040px){.dcx [data-heroimg]{position:relative!important;height:430px!important;max-width:620px;margin:0 auto!important}
.dcx [data-ragrid]{grid-template-columns:minmax(0,1fr)!important}
.dcx [data-ranav]{display:none!important}
}

.dch-3d1ded89:hover{transform:translateY(-1px) !important;color:#FFFFFF !important}
.dch-df2ff70f:hover{transform:translateY(-2px) !important;color:#FFFFFF !important}
